#!/usr/bin/env python3
"""Builds Notareal_Source_Library_v0.9.zip: a zip of zips. One zip per ROM we built (source only), the dev kit, the ROM data library,
test harnesses and documents. Third-party toolchains, commercial ROM dumps, reference photos and build outputs are left out on purpose."""
import os, zipfile, sys, time, io, shutil
H = '/home/claude'; OUT = H + '/out/lib'; shutil.rmtree(OUT, ignore_errors=True); os.makedirs(OUT)
SKIP_DIRS = {'build', 'build_test', '__pycache__', 'node_modules', '.git', 'refs', 'ref', 'photos', 'streetview', 'filesystem', 'dist_old'}
SKIP_EXT = {'.nds', '.gba', '.gb', '.gbc', '.sfc', '.smc', '.z64', '.n64', '.v64', '.iso', '.o', '.rel', '.elf', '.a', '.sym', '.symfull', '.pyc', '.log', '.cue'}
MAXMB = 6
def walk(root, extra_skip_dirs=(), keep_ext=(), keep_dirs=(), max_mb=MAXMB):
    for d, dirs, files in os.walk(root):
        dirs[:] = [x for x in dirs if (x not in SKIP_DIRS or x in keep_dirs) and x not in extra_skip_dirs and not x.startswith('.git')]
        for f in files:
            p = os.path.join(d, f); e = os.path.splitext(f)[1].lower()
            if e in SKIP_EXT and e not in keep_ext: continue
            try:
                if os.path.getsize(p) > max_mb << 20: continue
            except OSError: continue
            yield p, os.path.relpath(p, root)
def make_zip(name, parts, readme=None, **kw):
    path = f'{OUT}/{name}'; n = 0
    with zipfile.ZipFile(path, 'w', zipfile.ZIP_DEFLATED, compresslevel=6) as z:
        if readme: z.writestr('README_BUILD.txt', readme)
        for root, prefix in parts:
            if os.path.isfile(root): z.write(root, os.path.join(prefix, os.path.basename(root))); n += 1; continue
            for p, rel in walk(root, **kw):
                z.write(p, os.path.join(prefix, rel)); n += 1
    print(f'{name}: {n} files, {os.path.getsize(path) / 1048576:.1f} MB'); return path
def R(rom, plat, tool, cmd, note=''):
    return f'ROM(s): {rom}\nPlatform: {plat}\nToolchain: {tool}\nBuild: {cmd}\nNotes: {note}\nMost scripts have /home/claude/... paths written into them; change them to where you unpack this.\nSee ROM_INDEX.md in the library root for the full list.\n'
os.makedirs(OUT + '/stage', exist_ok=True)
Z = {}
# ---- 01 devkit
Z['devkit'] = make_zip('devkit_v0.9_source.zip', [(H + '/notareal-kit', 'notareal-kit-v0.9')], extra_skip_dirs={'build'}, keep_ext={'.nds', '.sfc'}, max_mb=8)
# engine templates (.nds/.sfc inside kit) are kept: they are the compiled engine templates the studio embeds
# ---- 02 roms
Z['icw'] = make_zip('ICW_Indie_Promotion_DS_source.zip', [(H + '/icw', 'icw'), (H + '/out/ICW_Indie_Promotion_DESIGN.md', 'icw')], R('ICW_Indie_Promotion.nds and the icw_*.nds prototypes (ring prototype, v2, v3, caw, create theme, story ch1, open world, holo hits, touchfix ch2)', 'Nintendo DS (DraStic on RG DS Plus)', 'BlocksDS + GCC 13 arm-none-eabi (see icw/TOOLCHAIN.md for the local patches)', 'cd icw/rom && BLOCKSDS=<blocksds> make', 'Reference photos in icw/refs were left out.'))
Z['cs'] = make_zip('Convenience_Store_GBC_source.zip', [(H + '/cs', 'cs')], R('convenience-store.gbc', 'Game Boy Color', 'GBDK-2020 (not included)', 'sh cs/build.sh', 'work/ is the live tree; src_zip is the earlier source drop.'))
Z['cs64'] = make_zip('Convenience_Store_64_N64_source.zip', [(H + '/cs64', 'cs64')], R('convenience-store-64.z64', 'Nintendo 64 (ParaLLEl N64 core)', 'libdragon preview + mips toolchain (not included)', 'cd cs64 && make  (assets: PNGs in assets/ are converted to filesystem/ by the Makefile)', 'filesystem/ is generated and left out.'))
Z['qm64'] = make_zip('Quick_Mart_64_N64_source.zip', [(H + '/qm64', 'qm64')], R('convenience-store-64-quick-mart.z64', 'Nintendo 64', 'libdragon preview', 'cd qm64 && make', 'Fork of Convenience Store 64 focused on the Quick Mart.'))
Z['hounds'] = make_zip('Hounds_Reloaded_SNES_source.zip', [(H + '/hounds/src', 'hounds')], R('hounds_reloaded.sfc', 'Super Nintendo', '65816 assembler + SPC700 driver built by tools/*.py (see build.sh)', 'cd hounds && sh build.sh all', 'Fake-3D missions; assets generated by tools/make_*.py.'))
Z['mh'] = make_zip('Moonlight_Holler_GB_source.zip', [(H + '/mh/src', 'mh')], R('moonlight-holler.gb', 'Game Boy', 'GBDK-2020', 'cd mh && ./build.sh /path/to/gbdk   (Windows: build-windows.ps1)', 'Includes Dirt Road Brawler.'))
Z['sml'] = make_zip('Super_Moonlight_Holler_SNES_source.zip', [(H + '/sml', 'sml')], R('super-moonlight-holler.sfc (+ preview1-6 and the final)', 'Super Nintendo', 'PVSnesLib (devkitsnes, wla-dx) (not included)', 'cd sml && make', 'Hard-coded PVSNESLIB_HOME in Makefile.'))
Z['goodwill'] = make_zip('Goodwill_SNES_source.zip', [(H + '/goodwill', 'goodwill')], R('goodwill.sfc', 'Super Nintendo', 'Forked from the Super Moonlight Holler engine (PVSnesLib); tcc quirks listed in PLAN.md', 'cd game && python3 tools/make_all.py && python3 tools/fixbranch.py', 'ref/ photos of the real plaza left out.'))
Z['psx'] = make_zip('Mr_Domino_PSX_source.zip', [(H + '/psxdomino', 'psxdomino')], R('psx/domino_run.bin/.cue', 'PlayStation', 'PSn00bSDK + CMake (not included); kit files in notareal-kit/psx', 'cmake -S psxdomino -B build && cmake --build build', 'CMakeLists refers to /home/claude/notareal-kit/psx.'), keep_dirs={'build_assets'})
Z['n64tests'] = make_zip('N64_Test_ROMs_source.zip', [(H + '/n64tests', 'n64tests')], R('n64_tests/test0-cpu-only, test1-text-only, test2-3d-demo', 'Nintendo 64', 'libdragon', 'cd n64tests/<cpu|text|gl> && make', 'Used to find what breaks on the RG DS Plus N64 core.'))
Z['gbkit'] = make_zip('GB_Kit_source.zip', [(H + '/gbkit', 'gbkit')], R('(library for GB games)', 'Game Boy', 'GBDK-2020', '(header-only helpers: motion, rng, rpg_battle)'))
# ---- 03 data library
dl = [(H + '/catalog', 'catalog'), (H + '/tools', 'tools')] + [(H + '/out/' + f, 'out') for f in ('rom_catalog.sqlite', 'games.csv', 'systems.csv', 'functions.csv')] + [(H + '/notareal-kit/ds/library/code_db.json', 'library')]
Z['data'] = make_zip('ROM_Data_Library.zip', dl, R('(no ROM)', 'all', 'python3', 'tools/*.py rebuild the catalog from your own ROM dumps', 'Facts and numbers only. No ROM data is stored. rom_catalog.sqlite is the game physics / code database the studio uses.'))
# ---- 04 harnesses
hp = [(H + '/tc/n64/n64run.py', 'n64'), (H + '/tc/n64/logshim.c', 'n64'), (H + '/tc/n64/armrig', 'n64/armrig'), (H + '/tc/n64/glrig', 'n64/glrig'), (H + '/tc/psx/tcsrc', 'psx/tcsrc'), (H + '/icw/tools/dsrun.py', 'ds')]
hp = [x for x in hp if os.path.exists(x[0])]
Z['harness'] = make_zip('Test_Harnesses.zip', hp, R('(no ROM)', 'N64 / PSX / DS', 'python3, libretro cores, DeSmuME (not included)', 'see each script header', 'Headless runners used to boot-test ROMs and take screenshots.'), keep_ext={'.so'})
# ---- 05 documents
docs_parts = [(H + '/goodwill/DESIGN.md', 'goodwill'), (H + '/goodwill/PLAN.md', 'goodwill'), (H + '/icw/CAST_LOOKS.md', 'icw'), (H + '/icw/DESIGN.md', 'icw'), (H + '/icw/TOOLCHAIN.md', 'icw'), (H + '/out/ICW_Indie_Promotion_DESIGN.md', 'icw'), (H + '/notareal-kit/STATUS_AND_REMAINING.md', 'devkit'), (H + '/notareal-kit/HANDOFF.md', 'devkit'), (H + '/smh_in', 'smh_in_handoffs'), (H + '/research', 'research')]
Z['docs'] = make_zip('Design_and_Handoff_Documents.zip', [x for x in docs_parts if os.path.exists(x[0])], None, max_mb=2)
# ---- program
shutil.copy(H + '/out/NotarealStudio_Windows.zip', OUT + '/NotarealStudio_v0.9_Windows.zip') if os.path.exists(H + '/out/NotarealStudio_Windows.zip') else None
print('done')
